const https = require("https");
const fs = require("fs");

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  console.log("Downloading BungeeCord (latest CI build)");
  const jar = await get("https://ci.md-5.net/job/BungeeCord/lastSuccessfulBuild/artifact/bootstrap/target/BungeeCord.jar");
  if (jar.status !== 200) throw new Error(`BungeeCord download returned ${jar.status}`);
  fs.writeFileSync("bungee.jar", jar.body);
  console.log(`Saved bungee.jar (${(jar.body.length / 1024 / 1024).toFixed(1)} MB)`);
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
